def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    # Score mapping: 0 points -> "0", 1 -> "15", 2 -> "30", 3+ -> "40"
    score_map = {0: "0", 1: "15", 2: "30", 3: "40"}

    for point in points:
        # Check if game is already won (only happens at deuce with no-ad scoring)
        if a_points >= 3 and b_points >= 3:
            # At deuce/40-40, next point wins
            if point == "A":
                return "Game A"
            else:
                return "Game B"

        # Check if someone has already won (before deuce)
        if a_points >= 3 and b_points < 3:
            if a_points > b_points:
                return "Game A"
        if b_points >= 3 and a_points < 3:
            if b_points > a_points:
                return "Game B"

        # Award the point
        if point == "A":
            a_points += 1
        else:
            b_points += 1

        # Check if someone won after this point
        if a_points >= 3 and b_points < 3 and a_points > b_points:
            return "Game A"
        if b_points >= 3 and a_points < 3 and b_points > a_points:
            return "Game B"
        if a_points >= 3 and b_points >= 3:
            # At deuce (40-40), next point will win (handled in next iteration)
            pass

    # Game hasn't been won, return current score
    if a_points >= 3 and b_points >= 3:
        return "40-40"
    else:
        a_score = score_map.get(a_points, "40")
        b_score = score_map.get(b_points, "40")
        return f"{a_score}-{b_score}"

